package online.girisonfoodproducts.webviewapp;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;

public class MainActivity extends Activity {
 static final String API="https://www.girisonfoodproducts.online/api/products.php";
 static final String SITE="https://www.girisonfoodproducts.online/";
 int green=Color.rgb(9,75,44), gold=Color.rgb(221,169,63), cream=Color.rgb(250,247,237), ink=Color.rgb(34,42,35);
 LinearLayout root,content,productList,cartList; TextView status,cartBadge; EditText customerName,customerPhone,address;
 ArrayList<JSONObject> products=new ArrayList<>(); LinkedHashMap<String,CartItem> cart=new LinkedHashMap<>(); String category="All"; int page=0;
 static class CartItem { JSONObject product; int qty=1; CartItem(JSONObject p){product=p;} }
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(green);getWindow().setNavigationBarColor(green);showHome();loadProducts();}
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} 
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
 TextView button(String label,int color){TextView t=text(label,14,Color.WHITE,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(14),dp(12),dp(14),dp(12));t.setBackground(bg(color,14));return t;}
 void shell(String title){root=col();root.setBackgroundColor(cream);setContentView(root);LinearLayout top=row();top.setBackgroundColor(green);pad(top,18,14,18,14);LinearLayout brand=col();brand.addView(text("GIRISON",20,Color.WHITE,true));brand.addView(text("FOOD PRODUCTS  •  ASSAM ROYAL TEA",10,0xFFD9E7D9,true));top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));TextView cartBtn=button("🛒  Cart ("+cartCount()+")",gold);top.addView(cartBtn);cartBtn.setOnClickListener(v->showCart());root.addView(top);ScrollView sc=new ScrollView(this);content=col();pad(content,16,16,16,28);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=row();nav.setBackgroundColor(Color.WHITE);String[] labels={"⌂  Home","☕  Leaf","🍃  Dust","🛒  Cart"};for(int i=0;i<labels.length;i++){final int x=i;TextView n=text(labels[i],12,green,true);n.setGravity(Gravity.CENTER);pad(n,3,15,3,15);nav.addView(n,new LinearLayout.LayoutParams(0,-2,1));n.setOnClickListener(v->{if(x==0)showHome();else if(x==1){category="Leaf";showProducts();}else if(x==2){category="Dust";showProducts();}else showCart();});}root.addView(nav);}
 int cartCount(){int n=0;for(CartItem i:cart.values())n+=i.qty;return n;}
 void showHome(){page=0;shell("Home");LinearLayout hero=col();hero.setBackground(bg(green,24));pad(hero,20,24,20,24);hero.addView(text("A CUP FULL OF ASSAM",12,gold,true));TextView h=text("Rich aroma.\nPure Assam taste.",29,Color.WHITE,true);pad(h,0,10,0,8);hero.addView(h);hero.addView(text("Discover our carefully selected Leaf & Dust tea range, packed fresh for every day.",15,0xFFE3EDE3,false));TextView shop=button("EXPLORE TEA  →",gold);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,-2);bp.topMargin=dp(18);hero.addView(shop,bp);shop.setOnClickListener(v->{category="All";showProducts();});content.addView(hero);
 LinearLayout stats=row();stats.setPadding(0,dp(16),0,dp(16));String[][] items={{"🌿","Assam","Tea"},{"📦","Multiple","Pack sizes"},{"💚","Fresh","Quality"}};for(String[] it:items){LinearLayout c=col();c.setGravity(Gravity.CENTER);c.setBackground(bg(Color.WHITE,16));pad(c,5,15,5,15);c.addView(text(it[0],22,green,true));c.addView(text(it[1],14,ink,true));c.addView(text(it[2],11,Color.GRAY,false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(3),0,dp(3),0);stats.addView(c,p);}content.addView(stats);
 content.addView(text("Our tea collection",22,ink,true));content.addView(text("Choose a blend and pack size that suits you.",13,Color.DKGRAY,false));LinearLayout choices=row();choices.setPadding(0,dp(14),0,0);for(String s:new String[]{"🌿  Leaf Tea","🍃  Dust Tea"}){TextView b=button(s,green);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,0,dp(8),0);choices.addView(b,p);b.setOnClickListener(v->{category=s.contains("Leaf")?"Leaf":"Dust";showProducts();});}content.addView(choices);TextView browse=button("VIEW ALL PRODUCTS",gold);LinearLayout.LayoutParams bp2=new LinearLayout.LayoutParams(-1,-2);bp2.topMargin=dp(12);content.addView(browse,bp2);browse.setOnClickListener(v->{category="All";showProducts();});TextView about=text("Marketed by Girison Food Products",12,Color.GRAY,false);about.setGravity(Gravity.CENTER);pad(about,0,22,0,4);content.addView(about);}
 void loadProducts(){status=null;new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(API).openConnection();c.setRequestMethod("GET");c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/json");InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);JSONObject result=new JSONObject(out.toString("UTF-8"));if(!result.optBoolean("success",false))throw new Exception("API response was not successful");JSONArray arr=result.getJSONArray("products");ArrayList<JSONObject> got=new ArrayList<>();for(int i=0;i<arr.length();i++)got.add(arr.getJSONObject(i));runOnUiThread(()->{products.clear();products.addAll(got);if(page==1)showProducts();});c.disconnect();}catch(Exception e){runOnUiThread(()->{if(page==1){if(status!=null)status.setText("Could not load live products. Check internet and tap Retry.");}});}}).start();}
 String money(double d){return "₹"+String.format(Locale.US,"%.0f",d);} double price(JSONObject p){return p.optDouble("selling_price",0);}
 void showProducts(){page=1;shell("Products");content.addView(text("TEA STORE",12,gold,true));content.addView(text(category.equals("All")?"Find your favourite tea":"Assam Royal "+category+" Tea",25,ink,true));content.addView(text("Live prices from Girison Food Products",13,Color.DKGRAY,false));LinearLayout filters=row();filters.setPadding(0,dp(12),0,dp(12));for(String s:new String[]{"All","Leaf","Dust"}){TextView f=button(s,(category.equals(s)||(category.equals("All")&&s.equals("All")))?green:0xFF8A958C);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(2),0,dp(2),0);filters.addView(f,p);f.setOnClickListener(v->{category=s;showProducts();});}content.addView(filters);status=text("Loading live product catalogue…",14,Color.DKGRAY,false);content.addView(status);productList=col();content.addView(productList);renderProducts();TextView retry=button("↻  Refresh prices",gold);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.topMargin=dp(14);content.addView(retry,rp);retry.setOnClickListener(v->{status.setText("Refreshing…");loadProducts();});}
 void renderProducts(){if(productList==null)return;productList.removeAllViews();int shown=0;for(JSONObject p:products){String type=p.optString("product_type","Tea");if(!category.equals("All")&&!category.equalsIgnoreCase(type))continue;shown++;LinearLayout card=col();card.setBackground(bg(Color.WHITE,18));pad(card,14,14,14,14);LinearLayout r=row();TextView icon=text(type.equalsIgnoreCase("Leaf")?"🌿":"🍃",34,green,true);icon.setGravity(Gravity.CENTER);icon.setBackground(bg(cream,16));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(dp(70),dp(70));r.addView(icon,ip);LinearLayout details=col();pad(details,12,0,0,0);details.addView(text("Assam Royal "+type,17,ink,true));details.addView(text(p.optString("pack_size","Pack")+" pack",13,Color.DKGRAY,false));details.addView(text(money(price(p))+"  "+(p.optDouble("mrp",0)>price(p)?"MRP "+money(p.optDouble("mrp",0)):""),16,green,true));r.addView(details,new LinearLayout.LayoutParams(0,-2,1));card.addView(r);boolean stock=p.optBoolean("in_stock",p.optInt("stock_qty",999)>0);TextView add=button(stock?"＋  ADD TO CART":"OUT OF STOCK",stock?green:0xFF888888);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,-2);ap.topMargin=dp(12);card.addView(add,ap);add.setEnabled(stock);add.setOnClickListener(v->{String id=p.optString("id",type+"-"+p.optString("pack_size"));if(cart.containsKey(id))cart.get(id).qty++;else cart.put(id,new CartItem(p));Toast.makeText(this,"Added to cart",Toast.LENGTH_SHORT).show();showProducts();});LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);productList.addView(card,cp);}if(status!=null)status.setText(products.isEmpty()?"No products returned by API. Tap Refresh.":shown+" products available"+(category.equals("All")?"":" in "+category));}
 double total(){double t=0;for(CartItem i:cart.values())t+=price(i.product)*i.qty;return t;}
 void showCart(){page=2;shell("Your Cart");content.addView(text("YOUR BASKET",12,gold,true));content.addView(text("Review your order",25,ink,true));if(cart.isEmpty()){content.addView(text("Your cart is empty. Explore our Assam Royal Tea range and add your favourite packs.",15,Color.DKGRAY,false));TextView b=button("BROWSE TEA",green);content.addView(b);b.setOnClickListener(v->{category="All";showProducts();});return;}cartList=col();content.addView(cartList);renderCart();content.addView(text("Customer details",20,ink,true));customerName=field("Customer name");customerPhone=field("Phone number");address=field("Delivery address (optional)");content.addView(customerName);content.addView(customerPhone);content.addView(address);TextView checkout=button("ORDER ON WHATSAPP  →",green);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(14);content.addView(checkout,bp);checkout.setOnClickListener(v->checkout());TextView note=text("Your order opens in WhatsApp for you to review and send. Prices are fetched from the live product API.",12,Color.GRAY,false);pad(note,0,12,0,0);content.addView(note);}
 EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(14);e.setHint(hint);e.setPadding(dp(14),dp(8),dp(14),dp(8));e.setBackground(bg(Color.WHITE,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(9);e.setLayoutParams(p);return e;}
 void renderCart(){cartList.removeAllViews();for(String id:new ArrayList<>(cart.keySet())){CartItem item=cart.get(id);LinearLayout r=row();r.setBackground(bg(Color.WHITE,14));pad(r,12,12,12,12);LinearLayout d=col();d.addView(text(item.product.optString("product_type")+" Tea · "+item.product.optString("pack_size"),15,ink,true));d.addView(text(money(price(item.product))+" each",13,Color.DKGRAY,false));r.addView(d,new LinearLayout.LayoutParams(0,-2,1));TextView minus=button("−",0xFF7D897F);TextView qty=text(" "+item.qty+" ",15,ink,true);TextView plus=button("+",green);r.addView(minus);r.addView(qty);r.addView(plus);minus.setOnClickListener(v->{item.qty--;if(item.qty<=0)cart.remove(id);showCart();});plus.setOnClickListener(v->{item.qty++;showCart();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(8);cartList.addView(r,p);}TextView totalView=text("Order total: "+money(total()),21,green,true);pad(totalView,4,12,4,18);cartList.addView(totalView);}
 void checkout(){String name=customerName.getText().toString().trim(),phone=customerPhone.getText().toString().trim(),addr=address.getText().toString().trim();if(name.isEmpty()||phone.isEmpty()){new AlertDialog.Builder(this).setMessage("Please enter customer name and phone number.").setPositiveButton("OK",null).show();return;}StringBuilder msg=new StringBuilder("Hello Girison Food Products! I would like to place an Assam Royal Tea order.\n\nCustomer: "+name+"\nPhone: "+phone);if(!addr.isEmpty())msg.append("\nAddress: ").append(addr);msg.append("\n\nORDER DETAILS\n");for(CartItem i:cart.values())msg.append("• ").append(i.product.optString("product_type")).append(" Tea - ").append(i.product.optString("pack_size")).append(" × ").append(i.qty).append(" = ").append(money(price(i.product)*i.qty)).append("\n");msg.append("\nTotal: ").append(money(total())).append("\n\nMarketed by Girison Food Products");try{Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("text/plain");intent.putExtra(Intent.EXTRA_TEXT,msg.toString());intent.setPackage("com.whatsapp");startActivity(intent);}catch(Exception ex){try{Intent intent=new Intent(Intent.ACTION_SEND);intent.setType("text/plain");intent.putExtra(Intent.EXTRA_TEXT,msg.toString());startActivity(Intent.createChooser(intent,"Send order with"));}catch(Exception ignored){Toast.makeText(this,"WhatsApp is not available on this device.",Toast.LENGTH_LONG).show();}}}
 @Override public void onBackPressed(){if(page==2){category="All";showProducts();}else if(page==1)showHome();else super.onBackPressed();}
}
